export const getListProjectJournalUrl = (id: string,
    params?: ListProjectJournalParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${id}/journal?${stringifiedParams}` : `/api/projects/${id}/journal`
}

