export const getExportProjectChronicleUrl = (id: string,
    params?: ExportProjectChronicleParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${id}/chronicle?${stringifiedParams}` : `/api/projects/${id}/chronicle`
}

